/* One-step distinguishability refinement from accepting/nonaccepting blocks.
   Complete binary DFA: n, accepting flags, two destinations per state. */
#include <stdio.h>
int main(void){int n,f[32],t[32][2],block[32],newblock[32],change=1;if(scanf("%d",&n)!=1||n<1||n>32)return 1;for(int i=0;i<n;i++)if(scanf("%d",&f[i])!=1||(f[i]!=0&&f[i]!=1))return 1;for(int i=0;i<n;i++)for(int c=0;c<2;c++)if(scanf("%d",&t[i][c])!=1||t[i][c]<0||t[i][c]>=n)return 1;for(int i=0;i<n;i++)block[i]=f[i];while(change){change=0;int next=0;for(int i=0;i<n;i++){int found=-1;for(int j=0;j<i;j++)if(block[i]==block[j]&&block[t[i][0]]==block[t[j][0]]&&block[t[i][1]]==block[t[j][1]]){found=newblock[j];break;}newblock[i]=found<0?next++:found;}for(int i=0;i<n;i++)if(newblock[i]!=block[i])change=1;for(int i=0;i<n;i++)block[i]=newblock[i];}int groups=0;for(int i=0;i<n;i++)if(block[i]+1>groups)groups=block[i]+1;printf("equivalence_classes=%d\n",groups);for(int i=0;i<n;i++)printf("%d:%d\n",i,block[i]);return 0;}